    pre: `var SIGN_LABELS=["UPLOAD","NOODLES","CYBER","NEXUS","GHOST","DATA","RUN","JACK IN","SYNTHWAVE","PROTOCOL"];function buildLayer(ctx,W,H,skylineY,bW,bH,cols,seed,fillColor,windowColor,t){for(let i=0;i<cols;i++){const s=seed+i*7.3;const bx=i*bW-(bW*0.15);const bh=bH*(0.4+((Math.sin(s)*0.5+0.5))*0.6);const by=skylineY-bh;const bww=bW*(0.55+(Math.sin(s*1.7)*0.5+0.5)*0.35);ctx.fillStyle=fillColor;ctx.fillRect(bx,by,bww,bh);const wCols=Math.max(1,Math.floor(bww/7));const wRows=Math.max(1,Math.floor(bh/10));for(let wc=0;wc<wCols;wc++){for(let wr=0;wr<wRows;wr++){const wSeed=s+wc*3.1+wr*1.7;const lit=Math.sin(wSeed*12.9+t*0.08)>0.05;if(!lit)continue;const wx=bx+wc*7+2;const wy=by+wr*10+3;ctx.fillStyle=windowColor;ctx.fillRect(wx,wy,3,4);}}}}`,
